"""Génère toutes les pages à partir des données confirmées et des composants communs."""
from pathlib import Path
from html import escape
from urllib.parse import urlencode
import json, re

root=Path(__file__).resolve().parents[1]
dist=root/'dist'
data=json.loads((root/'data/entreprise.json').read_text())
origin=data['domain']
old=(dist/'index.html').read_text()
font=re.search(r'<link[^>]+href="https://use\.typekit\.net/[^\"]+"[^>]*>',old)
font=font[0] if font else ''
wa='https://wa.me/'+data['whatsapp']
widget=(root/'scripts/contact-widget.html').read_text()
widget=re.sub(r'https://wa.me/\d+',wa,widget)
nav=[('Nos bois','/bois-de-feu/'),('Stères & formats','/steres-et-formats/'),('Livraison','/livraison/'),('Façonnage sur place','/travail-a-facon/')]
org={'@context':'https://schema.org','@type':'Organization','@id':origin+'/#entreprise','name':data['name'],'url':origin+'/','telephone':'+'+data['whatsapp'],'logo':origin+'/assets/logo.svg'}

def button(label='Demander mon bois',url='/reservation/',light=False):
 return f'<a class="button{" button--light" if light else ""}" href="{escape(url,quote=True)}">{label}</a>'
def request(**kwargs): return '/reservation/?'+urlencode(kwargs)
def photo(name,alt,eager=False,cls='',sizes='(max-width: 767px) 100vw, 50vw'):
 result = f'<img class="photo {cls}" src="/assets/{name}-1200.webp" srcset="/assets/{name}-600.webp 600w, /assets/{name}-800.webp 800w, /assets/{name}-1200.webp 1200w, /assets/{name}-2000.webp 2000w" sizes="{sizes}" width="1200" height="900" alt="{escape(alt,quote=True)}" loading="{"eager" if eager else "lazy"}"'+(' fetchpriority="high"' if eager else '')+'>'
 if name=='bois-hero':
  result=result.replace('height="900"','height="750"')
  return '<picture><source media="(max-width:767px)" srcset="/assets/bois-hero-mobile-600.webp 600w, /assets/bois-hero-mobile-800.webp 800w, /assets/bois-hero-mobile-1200.webp 1200w" sizes="100vw">'+result+'</picture>'
 return result
def header(slug):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if slug and (url.strip('/')==slug or slug.startswith(url.strip('/')+'/')) else '')+f'>{label}</a>' for label,url in nav)
 return f'''<a class="skip" href="#contenu">Aller au contenu</a><header class="header"><a class="brand" href="/" aria-label="Coppey Bois de feu, accueil"><img src="/assets/logo.svg" width="134" height="137" alt="Coppey Bois de feu"></a><nav aria-label="Navigation principale">{links}{button()}</nav><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu" aria-label="Ouvrir le menu"><span></span><span></span></button></header><nav id="mobile-menu" class="mobile-menu" aria-label="Navigation mobile" hidden>{links}{button()}</nav>'''
def footer():
 return f'''<footer class="footer"><div class="footer__top"><a class="brand" href="/"><img src="/assets/logo-creme.svg" width="134" height="137" alt="Coppey Bois de feu"></a><div><p>On parle de votre prochain feu ?</p><a class="footer__phone" href="tel:+{data['whatsapp']}">{data['phone']}</a></div></div><div class="footer__links"><a href="/bois-de-feu/">Nos bois</a><a href="/steres-et-formats/">Stères & formats</a><a href="/livraison/">Livraison & retrait</a><a href="/travail-a-facon/">Façonnage sur place</a><a href="/confidentialite/">Confidentialité</a></div></footer>{widget}'''
def cta(title='Du bois pour votre prochain feu ?',label='Demander mon bois',url='/reservation/'):
 return f'<section class="closing"><img src="/assets/veinage.svg" alt="" aria-hidden="true"><div><h2>{title}</h2>{button(label,url,True)}</div></section>'
def head(title,intro,action='Demander mon bois',url='/reservation/'):
 return f'<section class="page-head wrap"><div><a class="back-link" href="/">Accueil</a><h1>{title}</h1><p>{intro}</p></div>'+ (f'<div class="page-head__action">{button(action,url)}</div>' if action else '')+'</section>'
def icon(kind):
 paths={
  'wood':'<path d="m4 8 11-4 5 4-11 4-5-4Zm0 0v8l5 4 11-4V8M9 12v8m5-10v4m2-8 2 2"/>',
  'measure':'<rect x="3" y="7" width="18" height="10" rx="2"/><path d="M7 7v5m5-5v3m5-3v5"/>',
  'pin':'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  'message':'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-10A8.5 8.5 0 0 1 10.5 3h2a8.5 8.5 0 0 1 8.5 8.5Z"/><path d="M7 10h9M7 14h6"/>',
  'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>'}
 return '<svg class="line-icon" viewBox="0 0 24 24" width="32" height="32" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[kind]+'</svg>'
def order_flow():
 steps=[('wood','Votre bois','Choisissez l’essence, la longueur et la quantité en stères.','Choisir mon bois','/bois-de-feu/'),('pin','Votre adresse','Livraison avec accès remorque, ou retrait au dépôt.','Préparer ma demande','/reservation/'),('message','On confirme ensemble','Envoyez le message sur WhatsApp. Coppey confirme le prix et les possibilités.','Demander mon bois','/reservation/')]
 return '<section class="order-flow"><div class="wrap"><div class="section-heading"><h2>Du choix du bois<br>au prochain feu.</h2><p>Une demande simple. Le prix et l’organisation se confirment directement avec Coppey.</p></div><ol class="order-steps">'+''.join(f'<li>{icon(kind)}<h3>{title}</h3><p>{copy}</p><a class="text-link" href="{url}">{label}</a></li>' for kind,title,copy,label,url in steps)+'</ol></div></section>'
pages=[]
def write(slug,title,desc,body):
 url=origin+('/'+slug+'/' if slug else '/')
 structured=[org]
 if slug:structured.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Accueil','item':origin+'/'},{'@type':'ListItem','position':2,'name':title.split(' | ')[0],'item':url}]})
 metadata=f'<meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{origin}/assets/partage-bois-20260925.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Le bois de feu de Coppey, photographié au dépôt">'
 html=f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#3f3625"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="canonical" href="{url}"><link rel="icon" href="/assets/embleme.svg" type="image/svg+xml">{metadata}{font}<link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script>'+''.join('<script type="application/ld+json">'+json.dumps(obj,ensure_ascii=False)+'</script>' for obj in structured)+f'</head><body>{header(slug)}<main id="contenu">{body}</main>{footer()}<script type="application/json" id="site-data">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script></body></html>'
 dest=dist/slug;dest.mkdir(exist_ok=True,parents=True);(dest/'index.html').write_text(html);pages.append('/'+slug+'/' if slug else '/')

home=f'''
<section class="hero wrap"><div class="hero__copy"><h1>Du bon bois.<br>Du beau feu.</h1><p>Du bois sec, prêt à brûler.<br>Choisissez vos bûches, on prépare la suite ensemble.</p>{button()}<a class="text-link" href="/steres-et-formats/">Combien de stères me faut-il ?</a><ul class="hero-facts"><li>{icon('sun')}<span>Prêt à brûler</span></li><li>{icon('measure')}<span>25, 33 ou 50 cm</span></li><li>{icon('wood')}<span>Au stère</span></li></ul></div><div class="hero__photo">{photo('bois-hero','La matière et les nuances des bûches préparées chez Coppey',True)}</div></section>
<section class="home-woods section wrap"><div class="section-heading"><h2>Le bois a<br>du caractère.</h2><p>Des feuillus principalement vaudois, des résineux valaisans. Deux familles à découvrir, préparées chez Coppey.</p></div><div class="family-grid"><a class="family-card" href="/bois-de-feu/feuillus/">{photo('bois-cernes','Cernes et écorce du bois photographié chez Coppey')}<div><h3>Les feuillus</h3><p>Hêtre, dit fayard. Frêne.</p><span>Découvrir les feuillus</span></div></a><a class="family-card family-card--dark" href="/bois-de-feu/resineux/">{photo('bois-buche','Une bûche fendue préparée chez Coppey')}<div><h3>Les résineux</h3><p>Épicéa. Mélèze selon disponibilité.</p><span>Découvrir les résineux</span></div></a></div></section>
<section class="format-teaser"><div class="wrap format-teaser__inner"><div><h2>La bonne bûche.<br>La juste quantité.</h2><p>25, 33 ou 50 cm. Comparez les formats et estimez vos stères en quelques gestes.</p><a class="button button--light" href="/steres-et-formats/">Choisir mon format</a></div><a class="format-teaser__sizes" href="/steres-et-formats/" aria-label="Comparer les formats de 25, 33 et 50 centimètres"><span>25<small>cm</small></span><span>33<small>cm</small></span><span>50<small>cm</small></span></a></div></section>
<section class="story section wrap"><div>{photo('bois-depot','Le dépôt Coppey et ses bigbags de bois dans le paysage valaisan')}</div><div><h2>Votre bois.<br>À votre adresse.</h2><p>Une livraison en vrac, un accès pour la remorque. Et si vous le souhaitez, on range le bois, au temps passé.</p><p>Verbier, Val de Bagnes, Bas-Valais : indiquez votre adresse pour connaître les possibilités et le prix. Le retrait au dépôt est aussi possible.</p>{button("Préparer ma livraison",request(mode="livraison"))}<a class="text-link story__secondary" href="/livraison/">Livraison & retrait</a></div></section>{order_flow()}<section class="work-callout wrap"><h2>Du bois à préparer chez vous ?</h2><a class="text-link" href="/travail-a-facon/">Découvrez notre façonnage sur place</a></section>{cta()}
'''
write('','Bois de feu en Valais, demande pour Verbier | Coppey','Bois sec prêt à brûler : hêtre, frêne, épicéa et mélèze selon disponibilité. 25, 33 ou 50 cm, au stère. Livraison sur demande ou retrait au dépôt.',home)

woods=head('À chaque bois,<br>son caractère.','Hêtre, frêne, épicéa ou mélèze : découvrez les essences proposées par Coppey et choisissez celle que vous souhaitez pour votre foyer.')+f'''
<section class="family-grid section wrap section--topless"><article class="family-card">{photo('bois-cernes','Détail des cernes du bois chez Coppey',True)}<div><h2>Les feuillus</h2><p>Le hêtre, ou fayard en patois, et le frêne. Ils viennent principalement du canton de Vaud.</p><a class="text-link" href="/bois-de-feu/feuillus/">Hêtre & frêne</a></div></article><article class="family-card family-card--dark">{photo('bois-buche','Une bûche préparée au dépôt Coppey')}<div><h2>Les résineux</h2><p>L’épicéa du Valais. Et du mélèze valaisan, quand on en trouve.</p><a class="text-link" href="/bois-de-feu/resineux/">Épicéa & mélèze</a></div></article></section>
<section class="drying-band"><div class="wrap section"><h2>Le temps de sécher.<br>Le plaisir d’allumer.</h2><div class="drying-facts"><div><strong>9 <small>à</small> 10</strong><span>mois de séchage en bigbags</span></div><div><strong>15 <small>à</small> 20 <small>%</small></strong><span>d’humidité environ</span></div><p>Un bois sec, prêt à brûler, vendu au stère et livré en vrac.</p></div></div></section><section class="section wrap concise"><h2>Et la taille ?</h2><p>Choisissez un format adapté à votre appareil, puis estimez la quantité pour votre rangement.</p>{button('Voir les stères & formats','/steres-et-formats/')}</section>{cta()}
'''
write('bois-de-feu','Nos bois de feu : feuillus et résineux | Coppey','Découvrez les bois de Coppey : hêtre et frêne principalement vaudois, épicéa et mélèze valaisans. Séchage en bigbags et bois prêt à brûler.',woods)

for family,title,intro,items,image in [
 ('feuillus','Le hêtre.<br>Le frêne.','Deux feuillus, principalement du canton de Vaud. Préparés et séchés en bigbags chez Coppey.', [('Hêtre, ou fayard','Le nom change selon les habitudes. Chez nous, le fayard, c’est le hêtre. Disponible en 25, 33 et 50 cm.','hetre'),('Frêne','L’autre feuillu proposé par Coppey, lui aussi principalement vaudois. Disponible en 25, 33 et 50 cm.','frene')],'bois-cernes'),
 ('resineux','L’épicéa.<br>Le mélèze.','Des résineux qui viennent du Valais. L’épicéa fait partie de l’offre ; le mélèze est proposé selon les arrivages.', [('Épicéa','Un résineux valaisan proposé en bûches de 25, 33 ou 50 cm. Indiquez votre format et la quantité souhaitée.','epicea'),('Mélèze','Du mélèze du Valais, quand on en trouve. Demandez sa disponibilité avant de prévoir votre commande.','meleze')],'bois-buche')]:
 body=head(title,intro)+f'<section class="wood-profile wrap section section--topless"><div class="wood-profile__photo">{photo(image,"La matière du bois photographiée au dépôt Coppey",True)}</div><div>'+''.join(f'<article><h2>{name}</h2><p>{copy}</p>{button("Demander du "+("hêtre" if key=="hetre" else name.lower()),request(bois=key))}</article>' for name,copy,key in items)+'</div></section>'
 if family=='feuillus':body+=f'<section class="feature-note wrap"><img src="/assets/buches.svg" width="100" height="110" alt=""><div><h2>Un grand foyer ?</h2><p>Nous proposons aussi du 33 cm en grosses bûches, uniquement en feuillus.</p>{button("Demander du 33 cm en grosses bûches",request(format="33-gros"))}</div></section>'
 body+=f'<section class="section wrap concise"><h2>Du bois prêt à brûler.</h2><p>Séché environ {data["drying_months"]} en bigbags, pour une humidité d’environ 15 à 20 %. Prix et disponibilités sur demande.</p><a class="text-link" href="/steres-et-formats/">Choisir le format et les stères</a></section>'+cta()
 write('bois-de-feu/'+family,('Hêtre et frêne : bois feuillus' if family=='feuillus' else 'Épicéa et mélèze : bois résineux')+' | Coppey',intro.replace('<br>',' '),body)

format_cards=''.join(f'<a class="size-card" href="{request(format=f["id"])}"><strong>{f["id"]}<span> cm</span></strong><div class="log-length" style="--length:{int(f["id"])*1.5}%" aria-hidden="true"><span></span><span></span><span></span></div><p>1 stère ≈ {str(f["factor"]).replace(".",",")} m³ empilé</p><span class="text-link">Choisir {f["id"]} cm</span></a>' for f in data['formats'][:3])
formats=head('Vos bûches.<br>Vos stères.','Le bon format pour votre foyer, la bonne quantité pour votre rangement. Tout se prépare ici.')+f'''
<section class="section wrap section--topless"><div class="size-grid">{format_cards}</div><div class="format-note"><p><strong>Pour les grands foyers :</strong> du 33 cm en grosses bûches, uniquement en feuillus.</p><a class="text-link" href="{request(format='33-gros')}">Choisir les grosses bûches</a></div><p class="measure-note">Les volumes indiqués correspondent à du bois empilé. À la livraison, le bois est en vrac. Vérifiez la longueur acceptée par votre appareil.</p></section>
<section class="space-tool wrap" id="calculateur" aria-labelledby="tool-title"><div class="space-tool__intro"><h2 id="tool-title">Combien de stères<br>chez vous ?</h2><p>Mesurez l’espace où vous rangerez le bois. Ajustez les dimensions et choisissez votre longueur de bûche.</p><img src="/assets/buches-creme.svg" width="180" height="190" alt=""><p class="small-copy">Une estimation pour du bois empilé. La quantité finale se confirme avec Coppey.</p></div><div class="space-tool__surface"><div class="space-result" aria-live="polite"><output id="space-volume" for="space-width space-depth space-height space-length">≈ 1,4</output><span>stères estimés</span></div><fieldset class="space-inputs" disabled><legend class="sr-only">Votre rangement et vos bûches</legend><div><label for="space-length">Longueur des bûches</label><select id="space-length">{''.join(f'<option value="{f["id"]}"'+(' selected' if f['id']=='33' else '')+f'>{f["label"]}</option>' for f in data['formats'][:3])}</select></div>'''+''.join(f'<div><label for="space-{key}">{label}<output id="{key}-value">100 cm</output></label><input id="space-{key}" type="range" min="{low}" max="{high}" step="{step}" value="100"></div>' for key,label,low,high,step in [('width','Largeur',50,400,10),('depth','Profondeur',20,150,5),('height','Hauteur',20,200,10)])+f'''</fieldset><a class="button button--light" id="use-space" href="/reservation/">Utiliser cette estimation</a><noscript><p>Contactez-nous pour estimer votre besoin à partir de vos dimensions.</p></noscript></div></section>
<section class="section wrap story"><div>{photo('bois-livraison','Bigbags de bois au dépôt Coppey')}</div><div><h2>Un stère,<br>ça se prépare.</h2><p>Le bois sèche dans des bigbags. Des repères sur les sacs permettent de mesurer les quantités.</p><p>Nous vendons au stère, en vrac, à retirer au dépôt ou à livrer avec la remorque. Les tarifs sont établis sur demande.</p>{button()}</div></section>'''+cta()
write('steres-et-formats','Stères de bois et formats 25, 33, 50 cm | Coppey','Comparez les bûches de 25, 33 et 50 cm. Estimez vos stères avec les dimensions de votre rangement et préparez votre demande WhatsApp.',formats)

livraison=head('Du bois.<br>Jusqu’à chez vous.','Livraison en vrac, rangement si vous le souhaitez, ou retrait au dépôt. On s’organise avec vous.','Demander ma livraison',request(mode='livraison'))+f'''
<section class="story section wrap section--topless"><div>{photo('bois-depot','Bigbags de bois au dépôt Coppey, au pied des montagnes',True)}</div><div><h2>Une adresse.<br>Un accès remorque.</h2><p>Indiquez votre adresse et votre quantité : nous vous répondons avec les possibilités et le prix de livraison. La remorque doit pouvoir accéder au point de déchargement.</p><p>Vous souhaitez faire entasser le bois ? Nous pouvons nous en charger, avec une facturation au temps passé.</p>{button('Demander ma livraison',request(mode='livraison'))}</div></section><section class="service-pair wrap"><article><h2>Avant la neige,<br>c’est plus simple.</h2><p>Anticipez votre commande avant la fin novembre et décembre : les accès enneigés peuvent compliquer les livraisons.</p></article><article><h2>Vous venez<br>le chercher ?</h2><p>Le retrait au dépôt est possible. Contactez-nous pour préparer votre bois et convenir du passage.</p>{button('Préparer un retrait',request(mode='retrait'))}</article></section><section class="section wrap concise"><h2>Verbier et votre adresse.</h2><p>Pour une demande à Verbier, dans le Val de Bagnes ou ailleurs en Bas-Valais, envoyez-nous votre adresse. Chaque livraison et son tarif sont étudiés sur demande.</p><p>Le prix du bois est également sur demande. Tous types de paiement acceptés, modalités à convenir ensemble.</p></section>{order_flow()}{cta()}
'''
write('livraison','Livraison de bois à Verbier et retrait au dépôt | Coppey','Bois en vrac, livraison sur demande avec accès remorque. Rangement facturé au temps passé et retrait au dépôt possible. Préparez votre demande.',livraison)

service=head('Votre bois.<br>Notre machine.<br>Chez vous.','Triages forestiers, communes, particuliers : Coppey se déplace avec sa machine pour préparer votre bois en bigbags.','Demander une intervention',request(mode='faconnage'))+f'''<section class="story section wrap section--topless"><div>{photo('bois-machine','Équipement de préparation du bois chez Coppey',True)}</div><div><h2>Le façonnage,<br>sur votre terrain.</h2><p>Vous avez du bois à préparer ? Nous proposons de venir le façonner sur place et le mettre en bigbags.</p><p>Indiquez le lieu, le volume à préparer si vous le connaissez et l’accès disponible. Nous convenons avec vous de l’organisation et du prix.</p>{button('Parler de mon chantier',request(mode='faconnage'))}</div></section>'''+cta('Un chantier à préparer ?','Demander une intervention',request(mode='faconnage'))
write('travail-a-facon','Façonnage du bois sur place, mise en bigbags | Coppey','Coppey se déplace avec sa machine chez les triages forestiers, communes et particuliers pour préparer le bois en bigbags. Intervention sur demande.',service)

options=''.join(f'<option value="{w["id"]}">{w["name"]}</option>' for w in data['wood'])
lengths=''.join(f'<option value="{f["id"]}">{f["label"]}</option>' for f in data['formats'])
reservation=head('Votre prochain feu.<br>Un message suffit.','Choisissez votre bois et indiquez où il doit arriver. Nous vous répondons sur WhatsApp avec le prix et les possibilités.',action=None)+f'''
<section class="request-layout section wrap section--topless"><form id="wood-request"><fieldset id="request-fields" disabled><legend class="sr-only">Votre demande à Coppey</legend><div class="field"><label for="first-name">Votre prénom *</label><input id="first-name" name="prenom" required maxlength="80" autocomplete="given-name" placeholder="Votre prénom"></div><fieldset class="mode-picker"><legend>Comment souhaitez-vous votre bois ?</legend><div><label><input type="radio" name="mode" value="livraison" checked><span>Livraison</span></label><label><input type="radio" name="mode" value="retrait"><span>Retrait au dépôt</span></label><label><input type="radio" name="mode" value="faconnage"><span>Façonnage chez vous</span></label></div></fieldset><div id="wood-choice" class="field-row"><div class="field"><label for="wood">Votre bois</label><select id="wood" name="bois"><option value="conseil">Conseillez-moi</option>{options}</select></div><div class="field"><label for="length">Votre format</label><select id="length" name="format"><option value="conseil">Conseillez-moi</option>{lengths}</select></div></div><p class="field-help" id="large-log-note" hidden>Les grosses bûches de 33 cm sont proposées uniquement en feuillus.</p><div class="field"><label for="quantity" id="quantity-label">Quantité en stères</label><input id="quantity" name="quantite" maxlength="160" placeholder="Ex. 2 stères, ou à conseiller"><p class="field-help" id="space-estimate-note" hidden></p><a class="field-help field-link" href="/steres-et-formats/#calculateur">Estimer mes stères</a></div><div class="field" id="address-field"><label for="address" id="address-label">Adresse de livraison *</label><textarea id="address" name="adresse" rows="2" required maxlength="300" autocomplete="street-address" placeholder="Rue, numéro, NPA et localité"></textarea></div><details class="request-details"><summary>Une date, un rangement, une précision ?</summary><div class="field"><label for="timing">Pour quand ?</label><input id="timing" name="periode" maxlength="120" placeholder="Avant mon séjour, cet automne…"></div><label class="check-line" id="stacking-field"><input id="stacking" type="checkbox"><span>J’aimerais aussi faire ranger le bois.<small>Facturé au temps passé.</small></span></label><div class="field"><label for="message">Votre précision</label><textarea id="message" name="precision" rows="3" maxlength="1000" placeholder="Accès de la remorque, consigne, question…"></textarea></div></details><a id="whatsapp-send" class="button button--whatsapp" href="{wa}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Continuer sur WhatsApp</a><p class="field-help">Le message s’ouvre dans WhatsApp. Vous l’envoyez après relecture. Prix et disponibilité confirmés par Coppey.</p></fieldset><noscript><p>Écrivez-nous directement : <a href="{wa}">ouvrir WhatsApp</a>, ou appelez le <a href="tel:+{data['whatsapp']}">{data['phone']}</a>.</p></noscript></form><aside class="request-aside"><img src="/assets/buches-creme.svg" width="85" height="90" alt=""><h2>Votre message,<br>déjà prêt.</h2><label class="sr-only" for="message-preview">Message préparé pour WhatsApp</label><textarea id="message-preview" readonly rows="12"></textarea><button id="copy-message" class="copy-button" type="button">Copier le message</button><p id="copy-status" role="status"></p></aside></section>'''
write('reservation','Demander du bois de feu sur WhatsApp | Coppey','Choisissez votre essence, format et quantité en stères, ajoutez votre adresse de livraison et ouvrez votre demande sur WhatsApp. Prix sur demande.',reservation)
privacy=head('Vos informations,<br>simplement.','Comment le site prépare votre demande et vous met en relation avec Coppey.',action=None)+f'''<article class="prose section wrap section--topless"><h2>Une demande préparée sur votre appareil</h2><p>Le formulaire compose votre message dans votre navigateur. Votre prénom, votre adresse, vos choix et vos précisions ne sont pas enregistrés dans une base de données du site ni dans le stockage de votre navigateur.</p><h2>Le passage à WhatsApp</h2><p>Quand vous cliquez sur « Continuer sur WhatsApp », le texte de votre demande, y compris l’adresse renseignée, est transmis à WhatsApp dans le lien. Vous relisez puis envoyez vous-même le message. WhatsApp applique ses propres conditions de traitement des données.</p><p>L’adresse sert à préparer la livraison ou une intervention sur place. Elle n’est pas demandée pour un retrait au dépôt. Les informations reçues sont utilisées par Coppey pour répondre à votre demande et organiser la prestation convenue.</p><h2>La bulle de contact</h2><p>Un repère temporaire de session évite de réafficher la bulle d’aide. Il ne contient pas les informations du formulaire.</p><h2>Hébergement et services externes</h2><p>Le site de présentation est hébergé sur GitHub Pages. L’hébergeur peut conserver des informations techniques de connexion, notamment pour la sécurité de son service. Ce site ne comporte ni outil de mesure d’audience ni traceur publicitaire. Si Stolzl est chargée depuis Adobe Fonts, votre navigateur contacte Adobe pour afficher la police.</p><h2>Une question ?</h2><p>Pour une question relative à votre demande ou à vos informations, contactez Coppey Bois de feu au <a href="tel:+{data['whatsapp']}">{data['phone']}</a>.</p></article>'''
write('confidentialite','Confidentialité | Coppey Bois de feu','Informations utilisées pour votre demande WhatsApp, adresse de livraison et services externes du site Coppey Bois de feu.',privacy)
(dist/'404.html').write_text('<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Page introuvable | Coppey</title><link rel="icon" href="/assets/embleme.svg"><link rel="stylesheet" href="/style.css"></head><body><main class="page-head wrap"><img src="/assets/logo.svg" width="100" height="103" alt="Coppey Bois de feu"><h1>On s’est égarés.</h1><p>Retrouvons le chemin du bois.</p>'+button('Retour au site','/')+'</main></body></html>')
